             include: ["@emotion/react", "@emotion/styled"],
         },
         plugins: [
             checkerPlugin({
                 eslint: { lintCommand: "eslint . --ext .js,.jsx,.ts,.tsx", useFlatConfig: true },
                 typescript: true,
             }),
             istanbulPlugin,
             react(),
             svgr(),
         ],
         resolve: {
             alias: [
                 { find: "@root", replacement: srcRoot },
                 { find: "@assets", replacement: resolve(srcRoot, "assets") },
                 { find: "@components", replacement: resolve(srcRoot, "components") },
                 { find: "@constants", replacement: resolve(srcRoot, "constants") },
                 { find: "@contexts", replacement: resolve(srcRoot, "contexts") },
                 { find: "@hooks", replacement: resolve(srcRoot, "hooks") },
                 { find: "@i18n", replacement: resolve(srcRoot, "i18n") },
                 { find: "@layouts", replacement: resolve(srcRoot, "layouts") },
                 { find: "@models", replacement: resolve(srcRoot, "models") },
                 { find: "@services", replacement: resolve(srcRoot, "services") },
                 { find: "@themes", replacement: resolve(srcRoot, "themes") },
                 { find: "@utils", replacement: resolve(srcRoot, "utils") },
                 { find: "@views", replacement: resolve(srcRoot, "views") },
             ],
         },
         server: {
             allowedHosts: ["login.example.com", ...allowedHosts],
